import React, { useState } from "react";
import { ATTENTION_TOKENS, ATTENTION } from "../learnViz";

/* 0.3 — Attention. Hover a highlighted word to see what it looks at.
   "it" resolving to "animal" is the classic example, and it is the moment
   the transformer stops being magic and becomes a weighting scheme. */

const ASKABLE = Object.keys(ATTENTION);

export default function AttentionMap() {
  const [focus, setFocus] = useState("it");
  const weights = ATTENTION[focus] || [];
  const max = Math.max(...weights, 0.0001);

  // Strongest target that isn't the word itself — a token attending mostly to
  // its own position is true but tells the reader nothing.
  const topIndex = weights.reduce(
    (best, w, i) =>
      ATTENTION_TOKENS[i] !== focus && w > (weights[best] ?? -1) ? i : best,
    weights.findIndex((_, i) => ATTENTION_TOKENS[i] !== focus)
  );

  return (
    <div className="viz">
      <p className="viz-label">
        Which word is looking? <span className="viz-muted">(hover / tab)</span>
      </p>

      <div className="attn-sentence">
        {ATTENTION_TOKENS.map((t, i) => {
          const askable = ASKABLE.includes(t);
          const w = weights[i] || 0;
          return (
            <span
              key={i}
              className={`attn-tok ${askable ? "askable" : ""} ${
                focus === t ? "focus" : ""
              }`}
              style={{ "--w": (w / max).toFixed(3) }}
              onMouseEnter={() => askable && setFocus(t)}
              onFocus={() => askable && setFocus(t)}
              tabIndex={askable ? 0 : -1}
              role={askable ? "button" : undefined}
              aria-label={askable ? `attention from ${t}` : undefined}
            >
              {t}
            </span>
          );
        })}
      </div>

      <div className="attn-bars" aria-hidden="true">
        {ATTENTION_TOKENS.map((t, i) => (
          <div key={i} className="attn-bar-col">
            <div
              className="attn-bar"
              style={{ height: `${((weights[i] || 0) / max) * 100}%` }}
            />
          </div>
        ))}
      </div>

      <p className="viz-note" aria-live="polite">
        <strong>“{focus}”</strong> spends most of its attention on{" "}
        <strong>“{ATTENTION_TOKENS[topIndex]}”</strong>. That is the entire
        trick: every token is a blend of the tokens it decided were relevant.
      </p>
      <p className="viz-caveat">
        Illustrative weights on the canonical example sentence — a real head
        from a real model is noisier and there are dozens of them per layer,
        each attending to something different.
      </p>
    </div>
  );
}
