import React, { useEffect, useRef, useState } from "react";

import "./FractalBloom.css";

/* A tree that draws itself, sways, leans toward the pointer, drops petals,
   and — where the page gives it something to stand for — turns its limbs into
   a navigable table of contents.

   Ported from the shadcn/Tailwind original to this codebase's stack (plain JS,
   a stylesheet instead of utility classes, no framer-motion) and then taken
   several steps past it:

   - it fills its own box, not the viewport, and measures itself to fit;
   - the canvas is transparent, so it sits over whatever is behind it;
   - it grows as the reader scrolls through it rather than on a timer;
   - the eight branches at the third fork can be handed real subjects, in
     which case they take that subject's colour, light up under the pointer
     and can be clicked. */

const MAX_DEPTH = 10;
const LERP = 0.09;

/* The forks open by this much with nothing near them. The pointer adds to it
   rather than creating it, so the resting tree is already the shape it takes
   when you reach for it — just less of it. A tree that only opens up under
   the cursor spends most of its life looking pinched. */
const REST_SPREAD = 0.3;

/* The third fork gives exactly eight branches, and their seeds are 8..15 in
   left-to-right order — which is what makes them addressable. */
const LIMB_DEPTH = 3;
const LIMB_SEED0 = 1 << LIMB_DEPTH;

/* Rare on purpose. Petals raining down would turn a quiet hero into a
   screensaver; a click is allowed to be less restrained. */
const PETAL_EVERY = [4200, 9000];
const PETAL_MAX = 6;
const BURST_MAX = 26;

function wobble(seed, salt) {
  const n = Math.sin(seed * 12.9898 + salt * 78.233) * 43758.5453;
  return n - Math.floor(n);
}

function toRgb(value, fallback) {
  const hex = String(value || "").trim();
  if (/^#[0-9a-f]{6}$/i.test(hex)) {
    const n = parseInt(hex.slice(1), 16);
    return { r: (n >> 16) & 255, g: (n >> 8) & 255, b: n & 255 };
  }
  if (/^#[0-9a-f]{3}$/i.test(hex)) {
    return {
      r: parseInt(hex[1] + hex[1], 16),
      g: parseInt(hex[2] + hex[2], 16),
      b: parseInt(hex[3] + hex[3], 16),
    };
  }
  return fallback;
}

/* Nothing is drawn, measured or listened for until the page has finished
   loading and the browser has a spare moment. The tree is the least important
   thing on the page it decorates. */
function useDeferred(enabled) {
  const [ready, setReady] = useState(!enabled);

  useEffect(() => {
    if (!enabled) return undefined;
    let idle = 0;
    let timer = 0;

    const go = () => {
      if (typeof window.requestIdleCallback === "function") {
        idle = window.requestIdleCallback(() => setReady(true), {
          timeout: 1200,
        });
      } else {
        timer = setTimeout(() => setReady(true), 300);
      }
    };

    if (document.readyState === "complete") go();
    else window.addEventListener("load", go, { once: true });

    return () => {
      window.removeEventListener("load", go);
      if (idle && typeof window.cancelIdleCallback === "function") {
        window.cancelIdleCallback(idle);
      }
      if (timer) clearTimeout(timer);
    };
  }, [enabled]);

  return ready;
}

/* Hiding it in CSS would still mount a canvas and run observers on a phone.
   This keeps it out of the tree entirely below the width where it earns its
   place, and puts it back if the window grows. */
function useWide(minWidth) {
  const query = `(min-width: ${minWidth}px)`;
  const [wide, setWide] = useState(() => {
    if (!minWidth) return true;
    if (typeof window === "undefined" || !window.matchMedia) return false;
    return window.matchMedia(query).matches;
  });

  useEffect(() => {
    if (!minWidth || typeof window === "undefined" || !window.matchMedia) {
      return undefined;
    }
    const mq = window.matchMedia(query);
    const onChange = (e) => setWide(e.matches);
    setWide(mq.matches);
    /* Safari only grew addEventListener on MediaQueryList in 14. */
    if (mq.addEventListener) mq.addEventListener("change", onChange);
    else mq.addListener(onChange);
    return () => {
      if (mq.removeEventListener) mq.removeEventListener("change", onChange);
      else mq.removeListener(onChange);
    };
  }, [minWidth, query]);

  return wide;
}

export default function FractalBloom({
  className = "",
  color = "#4db6ac",
  bloom = "#e4a853",
  trunk = 0.2,
  originX = 0.5,
  defer = true,
  minWidth = 0,
  /* Up to eight subjects, left to right. Each takes one limb of the tree and
     paints it in that subject's colour: { id, accent }. Without them the
     whole tree is drawn in `color`. */
  limbs,
  ...rest
}) {
  const wrapRef = useRef(null);
  const canvasRef = useRef(null);
  const wide = useWide(minWidth);
  const ready = useDeferred(defer) && wide;

  /* Everything the animation loop needs but must not restart for. */
  const cfg = useRef({ color, bloom, limbs });
  cfg.current = { color, bloom, limbs };

  useEffect(() => {
    if (!ready) return undefined;
    const wrap = wrapRef.current;
    const canvas = canvasRef.current;
    if (!wrap || !canvas) return undefined;
    const ctx = canvas.getContext("2d");
    if (!ctx) return undefined;

    const reduced =
      typeof window.matchMedia === "function" &&
      window.matchMedia("(prefers-reduced-motion: reduce)").matches;

    let raf = 0;
    let spawn = 0;
    let onScreen = true;
    let size = { w: 0, h: 0 };
    let levels = MAX_DEPTH;
    let fit = { scale: 1, dx: 0, dy: 0 };
    let last = 0;

    /* Growth. The reader's scroll drives it; a floor keeps it from ever being
       a bare stump, and it never shrinks back once grown. */
    let depth = reduced ? MAX_DEPTH : MAX_DEPTH * 0.28;
    let wanted = depth;

    const target = { x: -9999, y: -9999 };
    const eased = { x: -9999, y: -9999 };

    /* The tree finishes growing and then just stands there, which reads as a
       picture until the visitor happens to move the mouse over it. So the
       moment it is grown it gets one breath of weather: a gust that decays,
       and a pass of the same lean a pointer would cause, moving across the
       crown. It shows what the thing does. Any real pointer movement cancels
       it — the visitor's hand always wins. */
    const BREEZE_MS = 3400;
    let breezeAt = -1;
    let breeze = 1;
    let touched = reduced;

    let tips = [];
    const petals = [];

    /* ---- geometry ------------------------------------------------------ */

    const limbOf = (seed, d) => {
      if (d < LIMB_DEPTH) return -1;
      /* Every branch below the third fork carries its limb's index: shift the
         seed back down to that generation. */
      let s = seed;
      for (let i = d; i > LIMB_DEPTH; i--) s = Math.floor(s / 2);
      return s - LIMB_SEED0;
    };

    /* Walk the tree once without drawing it: the bounding box tells us what
       scale keeps the crown inside the canvas, and the per-limb centroids are
       where the labels go. Recomputed on resize, never per frame. */
    const measure = (W, H, lv) => {
      let minX = Infinity;
      let maxX = -Infinity;
      let minY = Infinity;

      const walk = (x, y, angle, length, d, seed) => {
        const endX = x + Math.cos(angle) * length;
        const endY = y + Math.sin(angle) * length;
        if (endX < minX) minX = endX;
        if (endX > maxX) maxX = endX;
        if (endY < minY) minY = endY;

        if (d >= lv) return;
        const spread = Math.PI / 9 + (Math.PI / 8) * REST_SPREAD;
        const wl = wobble(seed, 1);
        const wr = wobble(seed, 2);
        walk(endX, endY, angle - spread * (0.8 + wl * 0.5), length * (0.72 + wl * 0.1), d + 1, seed * 2);
        walk(endX, endY, angle + spread * (0.8 + wr * 0.5), length * (0.72 + wr * 0.1), d + 1, seed * 2 + 1);
      };

      const baseX = W * originX;
      walk(baseX, H, -Math.PI / 2, H * trunk, 0, 1);

      /* Deliberately generous. A tree this shape is naturally about a third
         wider than the box that looks right for it — squeezing it in whole
         would cost a quarter of its size, and the point of the host page's
         edge mask is that overflow *dissolves* rather than being sliced. So
         the tree is allowed to spill, and this only steps in when a box is so
         small the crown would be more outside it than in. */
      const pad = Math.max(8, W * 0.015);
      const scale = Math.max(
        0.55,
        Math.min(
          1,
          (W * 1.5) / Math.max(1, maxX - minX),
          (H * 1.25) / Math.max(1, H - minY)
        )
      );

      const allow = W * 0.25;
      const left = baseX + (minX - baseX) * scale;
      const right = baseX + (maxX - baseX) * scale;
      let dx = 0;
      if (right > W - pad + allow) dx = W - pad + allow - right;
      if (left + dx < pad - allow) dx = pad - allow - left;

      return { scale, dx, dy: 0 };
    };

    const setSize = () => {
      const r = wrap.getBoundingClientRect();
      const w = Math.round(r.width);
      const h = Math.round(r.height);
      if (!w || !h) return;
      const dpr = Math.min(window.devicePixelRatio || 1, 2);
      canvas.width = Math.round(w * dpr);
      canvas.height = Math.round(h * dpr);
      canvas.style.width = `${w}px`;
      canvas.style.height = `${h}px`;
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      size = { w, h };
      levels = w < 380 ? MAX_DEPTH - 2 : MAX_DEPTH;
      fit = measure(w, h, levels);
    };

    /* ---- drawing -------------------------------------------------------- */

    const draw = (now) => {
      const { w: W, h: H } = size;
      if (!W || !H) return;
      const list = cfg.current.limbs || [];
      const base = toRgb(cfg.current.color, { r: 77, g: 182, b: 172 });
      const petal = toRgb(cfg.current.bloom, { r: 228, g: 168, b: 83 });
      const limbRgb = list.map((l) => toRgb(l.accent, base));

      const reach = (Math.min(W, H) * 0.95) / fit.scale;
      const bx = W * originX;
      const px = eased.x < -9000 ? -9999 : (eased.x - fit.dx - bx) / fit.scale + bx;
      const py = eased.y < -9000 ? -9999 : (eased.y - H) / fit.scale + H;
      const cap = Math.min(depth, levels);
      const collecting = cap >= levels;
      /* The wind: two sines at different periods so it never reads as a loop,
         and stronger the further from the trunk you get. `breeze` is the
         one-off gust that runs the first time the tree finishes growing. */
      const wind = reduced ? 0 : Math.sin(now * 0.00062) * 0.052 * breeze;
      const gust = reduced ? 0 : Math.sin(now * 0.00025 + 1.7) * 0.026 * breeze;

      ctx.clearRect(0, 0, W, H);
      ctx.save();
      ctx.translate(fit.dx, fit.dy);
      ctx.translate(bx, H);
      ctx.scale(fit.scale, fit.scale);
      ctx.translate(-bx, -H);
      ctx.lineCap = "round";
      if (collecting) tips = [];

      const branch = (x, y, angle, length, d, seed) => {
        if (d > cap) return;

        const li = limbOf(seed, d);
        const c = li >= 0 && limbRgb[li] ? limbRgb[li] : base;

        const sway = (wind + gust) * (d / levels) * (d / levels) * 3.1;
        const a = angle + sway;
        const endX = x + Math.cos(a) * length;
        const endY = y + Math.sin(a) * length;

        const partial = Math.min(1, cap - d + 1);
        const tipX = x + (endX - x) * partial;
        const tipY = y + (endY - y) * partial;

        const t = d / levels;
        ctx.beginPath();
        ctx.moveTo(x, y);
        ctx.lineTo(tipX, tipY);
        ctx.strokeStyle = `rgba(${c.r},${c.g},${c.b},${(
          (1 - t) * 0.5 +
          0.08
        ).toFixed(3)})`;
        ctx.lineWidth = Math.max(0.6, (1 - t) * 2.6);
        ctx.stroke();

        /* The crown. The outer three levels carry blooms, bigger and brighter
           the higher up they are — which is what makes it a canopy rather
           than a dusting of dots. */
        if (d >= levels - 3 && partial > 0.85) {
          const up = 1 - Math.min(1, tipY / (H * 0.9));
          const near = px > -9000 ? Math.hypot(tipX - px, tipY - py) : 1e9;
          const glow = Math.max(0, 1 - near / (reach * 0.55));
          const wa = wobble(seed, 3);
          const r = (0.9 + wa * 1.5) * (0.5 + up * 0.9) * (1 + glow * 0.5);
          const alpha = (0.2 + up * 0.5) * (0.7 + glow * 0.6);

          ctx.beginPath();
          ctx.arc(tipX, tipY, r, 0, Math.PI * 2);
          ctx.fillStyle = `rgba(${petal.r},${petal.g},${petal.b},${Math.min(
            0.95,
            alpha
          ).toFixed(3)})`;
          ctx.fill();

          if (up > 0.55 && wa > 0.45) {
            ctx.beginPath();
            ctx.arc(tipX, tipY, r * 3.4, 0, Math.PI * 2);
            ctx.fillStyle = `rgba(${petal.r},${petal.g},${petal.b},${(
              alpha * 0.14
            ).toFixed(3)})`;
            ctx.fill();
          }

          if (collecting && d === levels && up > 0.3) {
            tips.push({ x: tipX, y: tipY, r, limb: li });
          }
        }

        if (d >= levels) return;

        const dist = Math.hypot(endX - px, endY - py);
        const reachPull = px < -9000 ? 0 : Math.max(0, 1 - dist / reach);
        const pull = Math.max(REST_SPREAD, reachPull);
        const spread = Math.PI / 9 + (Math.PI / 8) * pull;
        const wl = wobble(seed, 1);
        const wr = wobble(seed, 2);

        branch(tipX, tipY, a - spread * (0.8 + wl * 0.5), length * (0.72 + wl * 0.1), d + 1, seed * 2);
        branch(tipX, tipY, a + spread * (0.8 + wr * 0.5), length * (0.72 + wr * 0.1), d + 1, seed * 2 + 1);
      };

      branch(bx, H, -Math.PI / 2, H * trunk, 0, 1);

      /* ---- whatever has come loose */
      const dt = last ? Math.min(64, now - last) : 16;
      for (let i = petals.length - 1; i >= 0; i--) {
        const p = petals[i];
        p.t += dt;
        p.vx *= 0.985;
        p.vy = Math.min(p.vy + 0.004 * (dt / 16), p.fall);
        p.x += p.vx * (dt / 16);
        p.y += p.vy * (dt / 16);
        p.sway += 0.02 * (dt / 16);
        const life = 1 - p.t / p.life;
        if (life <= 0 || p.y > H + 12) {
          petals.splice(i, 1);
          continue;
        }
        const fx = p.x + Math.sin(p.sway) * p.drift;
        /* It fades out as it reaches the foot of the tree rather than at some
           point in the air, so every petal is seen the whole way down. */
        const landing = Math.min(1, (H - p.y) / 80);
        const fade = Math.min(1, life * 1.6) * landing;
        p.spin += p.spinV * (dt / 16);

        /* A leaf, not a dot: a lens drawn from two curves, turned as it
           falls, and squashed across its width by a flutter term so it reads
           as something flat tumbling over rather than a ball dropping. */
        const flutter = Math.max(0.22, Math.abs(Math.cos(p.sway * 1.7)));
        const len = p.r * 1.9;
        const wide = p.r * 1.05;

        ctx.save();
        ctx.translate(fx, p.y);
        ctx.rotate(p.spin);
        ctx.scale(flutter, 1);
        ctx.beginPath();
        ctx.moveTo(0, -len);
        ctx.quadraticCurveTo(wide, -len * 0.1, 0, len);
        ctx.quadraticCurveTo(-wide, -len * 0.1, 0, -len);
        ctx.closePath();
        ctx.fillStyle = `rgba(${petal.r},${petal.g},${petal.b},${(
          fade * 0.85
        ).toFixed(3)})`;
        ctx.fill();

        /* The midrib — only worth drawing on the bigger ones. */
        if (p.r > 3) {
          ctx.beginPath();
          ctx.moveTo(0, -len * 0.82);
          ctx.lineTo(0, len * 0.82);
          ctx.strokeStyle = `rgba(0,0,0,${(fade * 0.16).toFixed(3)})`;
          ctx.lineWidth = 0.6;
          ctx.stroke();
        }
        ctx.restore();
      }

      ctx.restore();
      last = now;
    };

    /* ---- the loop ------------------------------------------------------- */

    /* Growth follows the reader rather than a timer: the tree fills in as its
       box comes into view and holds whatever it reached.

       The mapping has to reach 1 while the hero is simply *on screen*, not
       only after scrolling past it — the first version topped out around 90%
       of full depth for anyone who never scrolled, which is a whole
       generation of branches missing and reads as a smaller tree. */
    const readScroll = () => {
      const r = wrap.getBoundingClientRect();
      const seen =
        (window.innerHeight - r.top) / Math.max(1, window.innerHeight * 0.7);
      const p = Math.max(0, Math.min(1, seen));
      wanted = Math.max(wanted, MAX_DEPTH * (0.3 + 0.7 * p));
    };

    const frame = (now) => {
      const moving =
        Math.abs(eased.x - target.x) > 0.4 || Math.abs(eased.y - target.y) > 0.4;
      if (moving) {
        eased.x = eased.x < -9000 ? target.x : eased.x + (target.x - eased.x) * LERP;
        eased.y = eased.y < -9000 ? target.y : eased.y + (target.y - eased.y) * LERP;
      }
      if (depth < wanted) depth = Math.min(wanted, depth + 0.045);

      /* Kick it off on the first frame that is fully grown. */
      if (!touched && breezeAt < 0 && depth >= wanted) breezeAt = now;

      if (!touched && breezeAt >= 0) {
        const p = Math.min(1, (now - breezeAt) / BREEZE_MS);
        /* Gust first, fading as the pass goes by. */
        breeze = 1 + 2.1 * (1 - p) * (1 - p);
        if (p < 1) {
          /* A pointer that isn't there, sweeping left to right across the
             crown on an ease-in-out. */
          const e = p < 0.5 ? 2 * p * p : 1 - Math.pow(-2 * p + 2, 2) / 2;
          const { w: W, h: H } = size;
          eased.x = W * (0.12 + 0.82 * e);
          eased.y = H * (0.34 - 0.1 * Math.sin(e * Math.PI));
          target.x = eased.x;
          target.y = eased.y;
        } else {
          breeze = 1;
          touched = true;
          target.x = -9999;
          target.y = -9999;
        }
      }

      draw(now);

      /* Wind means there is always something to redraw; without it the tree
         idles once grown and settled. */
      if (reduced && !moving && depth >= wanted && petals.length === 0) {
        raf = 0;
        last = 0;
        return;
      }
      raf = requestAnimationFrame(frame);
    };

    const kick = () => {
      if (!raf && onScreen) raf = requestAnimationFrame(frame);
    };

    /* ---- petals --------------------------------------------------------- */

    const spawnPetal = (from, burst) => {
      petals.push({
        x: from.x,
        y: from.y,
        /* Bigger than the flower it left — on the tree a bloom is one of
           hundreds and wants to be small, in the air it is the only thing
           moving through empty space — but not so big it becomes a prop. */
        r: Math.max(2, from.r * (burst ? 1.5 : 1.7)),
        vx: burst ? (Math.random() - 0.5) * 2.6 : 0,
        vy: burst ? -0.6 - Math.random() * 0.9 : 0.25 + Math.random() * 0.2,
        /* Fast enough to actually reach the ground. At the old terminal
           speed a petal ran out of life somewhere around the middle of the
           canopy and blinked out mid-air. */
        fall: 0.62 + Math.random() * 0.55,
        drift: 6 + Math.random() * 16,
        sway: Math.random() * Math.PI * 2,
        spin: Math.random() * Math.PI * 2,
        spinV: (Math.random() - 0.5) * 0.045,
        t: 0,
        /* A safety net, not the thing that ends it: a petal's life is over
           when it lands. */
        life: 45000,
      });
    };

    const dropPetal = () => {
      if (petals.length >= PETAL_MAX || !tips.length) return;
      spawnPetal(tips[Math.floor(Math.random() * tips.length)], false);
      kick();
    };

    const scheduleDrop = () => {
      const [lo, hi] = PETAL_EVERY;
      spawn = setTimeout(() => {
        if (onScreen) dropPetal();
        scheduleDrop();
      }, lo + Math.random() * (hi - lo));
    };

    /* ---- pointer -------------------------------------------------------- */

    const toTree = (clientX, clientY) => {
      const r = wrap.getBoundingClientRect();
      const bx = size.w * originX;
      return {
        x: (clientX - r.left - fit.dx - bx) / fit.scale + bx,
        y: (clientY - r.top - size.h) / fit.scale + size.h,
        cx: clientX - r.left,
        cy: clientY - r.top,
      };
    };

    const onMove = (e) => {
      const r = wrap.getBoundingClientRect();
      target.x = e.clientX - r.left;
      target.y = e.clientY - r.top;

      kick();
    };

    const onLeave = () => {
      target.x = -9999;
      target.y = -9999;
      kick();
    };

    /* A click shakes the nearest branch. Listened for on the window, not the
       wrapper: the tree is decoration and must never take a click away from
       the page underneath it. */
    const onClick = (e) => {
      const box = wrap.getBoundingClientRect();
      if (
        e.clientX < box.left ||
        e.clientX > box.right ||
        e.clientY < box.top ||
        e.clientY > box.bottom
      ) {
        return;
      }
      const at = toTree(e.clientX, e.clientY);
      const near = tips
        .map((t) => ({ t, d: Math.hypot(t.x - at.x, t.y - at.y) }))
        .filter((o) => o.d < 220)
        .sort((a, b) => a.d - b.d)
        .slice(0, BURST_MAX);
      const chosen = near.length
        ? near
        : tips
            .map((t) => ({ t, d: Math.hypot(t.x - at.x, t.y - at.y) }))
            .sort((a, b) => a.d - b.d)
            .slice(0, 8);
      chosen.forEach((o) => spawnPetal(o.t, true));
      kick();
      /* Shaking the tree is all a click on the canvas does. Navigation lives
         on the label, which is a button and says where it goes — a click
         anywhere near a branch quietly changing the page would be a trap. */
    };

    setSize();
    draw(performance.now());
    readScroll();

    let ro = null;
    if (typeof ResizeObserver !== "undefined") {
      ro = new ResizeObserver(() => {
        setSize();
        if (!raf) draw(performance.now());
      });
      ro.observe(wrap);
    }

    const onScroll = () => {
      readScroll();
      kick();
    };
    /* Capture, because this site does not always scroll the window and scroll
       does not bubble. */
    window.addEventListener("scroll", onScroll, { passive: true, capture: true });
    window.addEventListener("mousemove", onMove, { passive: true });
    document.addEventListener("mouseleave", onLeave);
    window.addEventListener("click", onClick, { passive: true });

    let io = null;
    if (typeof IntersectionObserver !== "undefined") {
      io = new IntersectionObserver(
        ([e]) => {
          onScreen = e.isIntersecting;
          if (onScreen) kick();
          else if (raf) {
            cancelAnimationFrame(raf);
            raf = 0;
            last = 0;
          }
        },
        { rootMargin: "60px" }
      );
      io.observe(wrap);
    }

    kick();
    if (!reduced) scheduleDrop();

    return () => {
      if (raf) cancelAnimationFrame(raf);
      if (spawn) clearTimeout(spawn);
      window.removeEventListener("scroll", onScroll, { capture: true });
      window.removeEventListener("mousemove", onMove);
      document.removeEventListener("mouseleave", onLeave);
      window.removeEventListener("click", onClick);
      if (ro) ro.disconnect();
      if (io) io.disconnect();
    };
  }, [ready, trunk, originX]);

  if (!wide) return null;

  return (
    <div
      ref={wrapRef}
      className={`fbloom${ready ? " is-live" : ""}${
        className ? ` ${className}` : ""
      }`}
      aria-hidden="true"
      {...rest}
    >
      <canvas ref={canvasRef} className="fbloom-canvas" />
    </div>
  );
}
